@Tag("integration") class SingleCommandIT { @Test void allReplicasConverge(){var factory=new ClusterNodeFactory(){public Acceptor acceptor(NodeId id,paxoslocker.persistence.PersistentStore s){return new Acceptor(id,s);}public Replica replica(NodeId id,paxoslocker.transport.Transport t,paxoslocker.persistence.PersistentStore s,java.util.Collection<String> l){return new Replica(id,t,s,l);}public Leader leader(NodeId id,paxoslocker.transport.Transport t){return new Leader(id,t);}};try(var cluster=ClusterHarness.start(ClusterConfig.small(),factory)){cluster.submit(new ReserveLocker(UUID.randomUUID(),"c","locker-1"));cluster.awaitReplicaConvergence(Duration.ofSeconds(2));}} }
